import json, subprocess, sys

def call(tool, **kw):
    a = json.dumps(kw)
    r = subprocess.run(['ft2','call',tool,a],capture_output=True,text=True)
    out = r.stdout.strip()
    return out

def batch(path):
    r = subprocess.run(['ft2','batch',path],capture_output=True,text=True)
    return r.stdout.strip()[:2000], r.returncode

def cells(rows):
    """rows: list of (pattern,row,channel, dict)"""
    out=[]
    for pat,row,ch,d in rows:
        d2 = {"pattern":pat,"row":row,"channel":ch}
        d2.update(d)
        out.append({"name":"pattern_set_cell","arguments":d2})
    return out

def write_batch(path, calls):
    with open(path,'w') as f:
        json.dump(calls,f)
